import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CQIwe17B.js";const u=JSON.parse('{"title":"Project Pitch: Wanderly (Natours)","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),o={name:"00b-project-pitch.md"};function n(c,e,s,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="project-pitch-wanderly-natours" tabindex="-1">Project Pitch: Wanderly (Natours) <a class="header-anchor" href="#project-pitch-wanderly-natours" aria-label="Permalink to &quot;Project Pitch: Wanderly (Natours)&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><p>&quot;I built Wanderly, a high-performance nature tour booking platform engineered with a strict zero-JavaScript, 100% pure CSS architecture. By structuring the codebase using the production-grade 7-1 SASS pattern and BEM naming conventions, I created complex interactive user experiences—including a 3D perspective rotating card system, a pure CSS checkbox-driven fullscreen navigation overlay, and an anchor-targeted modal booking flow—running entirely on the browser&#39;s hardware-accelerated GPU compositor at a locked 60 frames per second.&quot;</p><hr><h2 id="_2-minute-technical-interview-pitch" tabindex="-1">2-Minute Technical Interview Pitch <a class="header-anchor" href="#_2-minute-technical-interview-pitch" aria-label="Permalink to &quot;2-Minute Technical Interview Pitch&quot;">​</a></h2><p>&quot;When approaching the Wanderly project, my primary engineering objective was to prove that complex, high-engagement web applications do not always require bulky JavaScript frameworks that bloat bundle sizes and degrade First Input Delay. I wanted to push the modern browser rendering engine to its limits using pure CSS3 and advanced SASS architectural principles.</p><p>I organized the styling into a strict 7-1 SASS architecture across abstracts, base rules, layout components, modular UI components, and page controllers. For state management, instead of loading a JavaScript library, I implemented declarative CSS state machines: the navigation utilizes the checkbox hack with adjacent sibling selectors to scale a radial background disc eighty-fold across the viewport; the interactive tour cards leverage CSS 3D transforms with 150-rem perspective and hidden backfaces to achieve fluid two-sided flips; and the booking modal relies on URL fragment targeting with the <code>:target</code> pseudo-class.</p><p>To ensure production resilience, I built an automated compilation pipeline with npm scripts: modern SCSS is compiled into raw CSS, merged with icon fonts, processed through PostCSS with Autoprefixer targeting the last ten browser versions, and compressed into a production artifact under 30 kilobytes. The layout engine features a custom mathematical float grid using <code>calc()</code> with micro-clearfixes, paired with a unified responsive mixin that adapts layouts across four distinct viewport tiers. The result is a travel booking landing page that scores 100 on Google Lighthouse performance with zero runtime layout thrashing.&quot;</p>',8)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
